   use pic_types, only: dp
   use trc_boys, only: BOYS_MMAX, boys_table, BOYS_NCHEB, BOYS_NGRID, BOYS_TMAX, BOYS_DT, BOYS_DTINV
   implicit none
   private
   public :: one_e_launch_11, one_e_11
   real(dp), parameter :: PI = 3.14159265358979323846_dp

contains

#include "inc/trc_boys_eval.inc"

   subroutine one_e_launch_11(n, idx, nshell, nao, natm, maxnp, sh_l, sh_np, sh_ao, sh_e, sh_c, sh_r, at_z, at_r, npair, p_i, p_j, smat, tmat, vmat)
      !! The pairs idx(1:n) of the pair list, all of class (1|1) with the
      !! higher-l shell first (the driver orients them, so a class is only (la|lb), la >= lb).
      integer,  intent(in)  :: n, idx(n)
      integer,  intent(in)    :: nshell, nao, natm, maxnp, npair
      integer,  intent(in)    :: p_i(npair), p_j(npair)
      integer,  intent(in)    :: sh_l(nshell), sh_np(nshell), sh_ao(nshell)
      real(dp), intent(in)    :: sh_e(maxnp, nshell), sh_c(maxnp, nshell)
      real(dp), intent(in)    :: sh_r(3, nshell)
      real(dp), intent(in)    :: at_z(natm), at_r(3, natm)
      real(dp), intent(inout) :: smat(nao, nao), tmat(nao, nao), vmat(nao, nao)
      integer :: k
      do concurrent(k = 1:n)
         call one_e_item_11(idx(k), nshell, nao, natm, maxnp, sh_l, sh_np, sh_ao, sh_e, sh_c, sh_r, at_z, at_r, npair, p_i, p_j, smat, tmat, vmat)
      end do
   end subroutine one_e_launch_11

   pure subroutine one_e_item_11(ij, nshell, nao, natm, maxnp, sh_l, sh_np, sh_ao, sh_e, sh_c, sh_r, at_z, at_r, npair, p_i, p_j, smat, tmat, vmat)
      !$acc routine seq
      integer,  intent(in)    :: ij
      integer,  intent(in)    :: nshell, nao, natm, maxnp, npair
      integer,  intent(in)    :: p_i(npair), p_j(npair)
      integer,  intent(in)    :: sh_l(nshell), sh_np(nshell), sh_ao(nshell)
      real(dp), intent(in)    :: sh_e(maxnp, nshell), sh_c(maxnp, nshell)
      real(dp), intent(in)    :: sh_r(3, nshell)
      real(dp), intent(in)    :: at_z(natm), at_r(3, natm)
      real(dp), intent(inout) :: smat(nao, nao), tmat(nao, nao), vmat(nao, nao)
      integer  :: ii, jj, a, c, mu, nu
      real(dp) :: sblk(9), tblk(9), vblk(9)
      ii = p_i(ij); jj = p_j(ij)
      call one_e_11(sh_np(ii), sh_np(jj), sh_e(:, ii), sh_c(:, ii), sh_e(:, jj), sh_c(:, jj), &
                       sh_r(:, ii), sh_r(:, jj), natm, at_z, at_r, sblk, tblk, vblk)
      ! Affine index, not a running counter (nvfortran 26.5 "Missing increment
      ! value", as in the gradient and multipole items). The matrices are
      ! symmetric, so the block and its transpose are written; on the diagonal
      ! block (ii == jj) that rewrites the same element with the same value.
      do c = 0, 2
         nu = sh_ao(jj) + c
         do a = 0, 2
            mu = sh_ao(ii) + a
            smat(mu, nu) = sblk(1 + a + 3*c)
            tmat(mu, nu) = tblk(1 + a + 3*c)
            vmat(mu, nu) = vblk(1 + a + 3*c)
            smat(nu, mu) = sblk(1 + a + 3*c)
            tmat(nu, mu) = tblk(1 + a + 3*c)
            vmat(nu, mu) = vblk(1 + a + 3*c)
         end do
      end do
   end subroutine one_e_item_11

   pure subroutine one_e_11(nprim_a, nprim_b, ea, ca, eb, cb, ra, rb, &
                               natm, zatm, ratm, sout, tout, vout)
      !! (1|1) one-electron block: overlap, kinetic, nuclear attraction.
      !!
      !! One routine for all three because they share the shell-pair quantities
      !! (zeta, P, the Gaussian product prefactor) and mqc needs all three to form
      !! the core Hamiltonian. Computing them together reads the primitive data
      !! once instead of three times.
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_b, natm
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a)
      real(dp), intent(in)  :: eb(nprim_b), cb(nprim_b)
      real(dp), intent(in)  :: ra(3), rb(3)
      real(dp), intent(in)  :: zatm(natm), ratm(3, natm)
      real(dp), intent(out) :: sout(9), tout(9), vout(9)

      integer  :: ip, jp, ic, k
      real(dp) :: al, bet, zeta, oo2z, xi, cc, tbb
      real(dp) :: px, py, pz, pax, pay, paz, pbx, pby, pbz
      real(dp) :: pcx, pcy, pcz, tval, vpref, rab2
      real(dp) :: abx, aby, abz, e0x, e0y, e0z
      real(dp) :: sx(0:1,0:3), sy(0:1,0:3), sz(0:1,0:3)
      real(dp) :: tx(0:1,0:1), ty(0:1,0:1), tz(0:1,0:1)
      real(dp) :: vn(10,0:2), vn0(10), vtmp(9)
      real(dp) :: f(0:BOYS_MMAX)
      real(dp) :: bax, bay, baz

      abx = ra(1) - rb(1); aby = ra(2) - rb(2); abz = ra(3) - rb(3)
      bax = -abx; bay = -aby; baz = -abz
      rab2 = abx*abx + aby*aby + abz*abz

      do k = 1, 9
         sout(k) = 0.0_dp; tout(k) = 0.0_dp; vout(k) = 0.0_dp
      end do

      do ip = 1, nprim_a
         al = ea(ip)
      do jp = 1, nprim_b
         bet = eb(jp)
         zeta = al + bet
         oo2z = 0.5_dp/zeta
         xi = al*bet/zeta
         cc = ca(ip)*cb(jp)
         tbb = 2.0_dp*bet*bet

         px = (al*ra(1) + bet*rb(1))/zeta
         py = (al*ra(2) + bet*rb(2))/zeta
         pz = (al*ra(3) + bet*rb(3))/zeta
         pax = px - ra(1); pay = py - ra(2); paz = pz - ra(3)
         pbx = px - rb(1); pby = py - rb(2); pbz = pz - rb(3)

         ! 1-D Gaussian-product prefactors; their product is
         ! (pi/zeta)^(3/2) exp(-xi |AB|^2), the 3-D overlap of two s functions.
         e0x = sqrt(PI/zeta)*exp(-xi*abx*abx)
         e0y = sqrt(PI/zeta)*exp(-xi*aby*aby)
         e0z = sqrt(PI/zeta)*exp(-xi*abz*abz)

         sx(0,0) = e0x
         sx(1,0) = pax*sx(0,0)
         sx(0,1) = pbx*sx(0,0)
         sx(1,1) = pbx*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(0,2) = pbx*sx(0,1) + 1.0_dp*oo2z*sx(0,0)
         sx(1,2) = pbx*sx(1,1) + 1.0_dp*oo2z*sx(0,1) + 1.0_dp*oo2z*sx(1,0)
         sx(0,3) = pbx*sx(0,2) + 2.0_dp*oo2z*sx(0,1)
         sx(1,3) = pbx*sx(1,2) + 1.0_dp*oo2z*sx(0,2) + 2.0_dp*oo2z*sx(1,1)
         sy(0,0) = e0y
         sy(1,0) = pay*sy(0,0)
         sy(0,1) = pby*sy(0,0)
         sy(1,1) = pby*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(0,2) = pby*sy(0,1) + 1.0_dp*oo2z*sy(0,0)
         sy(1,2) = pby*sy(1,1) + 1.0_dp*oo2z*sy(0,1) + 1.0_dp*oo2z*sy(1,0)
         sy(0,3) = pby*sy(0,2) + 2.0_dp*oo2z*sy(0,1)
         sy(1,3) = pby*sy(1,2) + 1.0_dp*oo2z*sy(0,2) + 2.0_dp*oo2z*sy(1,1)
         sz(0,0) = e0z
         sz(1,0) = paz*sz(0,0)
         sz(0,1) = pbz*sz(0,0)
         sz(1,1) = pbz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(0,2) = pbz*sz(0,1) + 1.0_dp*oo2z*sz(0,0)
         sz(1,2) = pbz*sz(1,1) + 1.0_dp*oo2z*sz(0,1) + 1.0_dp*oo2z*sz(1,0)
         sz(0,3) = pbz*sz(0,2) + 2.0_dp*oo2z*sz(0,1)
         sz(1,3) = pbz*sz(1,2) + 1.0_dp*oo2z*sz(0,2) + 2.0_dp*oo2z*sz(1,1)

         tx(0,0) = 1.0_dp*bet*sx(0,0) - tbb*sx(0,2)
         tx(1,0) = 1.0_dp*bet*sx(1,0) - tbb*sx(1,2)
         tx(0,1) = 3.0_dp*bet*sx(0,1) - tbb*sx(0,3)
         tx(1,1) = 3.0_dp*bet*sx(1,1) - tbb*sx(1,3)
         ty(0,0) = 1.0_dp*bet*sy(0,0) - tbb*sy(0,2)
         ty(1,0) = 1.0_dp*bet*sy(1,0) - tbb*sy(1,2)
         ty(0,1) = 3.0_dp*bet*sy(0,1) - tbb*sy(0,3)
         ty(1,1) = 3.0_dp*bet*sy(1,1) - tbb*sy(1,3)
         tz(0,0) = 1.0_dp*bet*sz(0,0) - tbb*sz(0,2)
         tz(1,0) = 1.0_dp*bet*sz(1,0) - tbb*sz(1,2)
         tz(0,1) = 3.0_dp*bet*sz(0,1) - tbb*sz(0,3)
         tz(1,1) = 3.0_dp*bet*sz(1,1) - tbb*sz(1,3)

         sout(1) = sout(1) + cc*sx(1,1)*sy(0,0)*sz(0,0)
         tout(1) = tout(1) + cc*(tx(1,1)*sy(0,0)*sz(0,0) &
            + sx(1,1)*ty(0,0)*sz(0,0) &
            + sx(1,1)*sy(0,0)*tz(0,0))
         sout(2) = sout(2) + cc*sx(0,1)*sy(1,0)*sz(0,0)
         tout(2) = tout(2) + cc*(tx(0,1)*sy(1,0)*sz(0,0) &
            + sx(0,1)*ty(1,0)*sz(0,0) &
            + sx(0,1)*sy(1,0)*tz(0,0))
         sout(3) = sout(3) + cc*sx(0,1)*sy(0,0)*sz(1,0)
         tout(3) = tout(3) + cc*(tx(0,1)*sy(0,0)*sz(1,0) &
            + sx(0,1)*ty(0,0)*sz(1,0) &
            + sx(0,1)*sy(0,0)*tz(1,0))
         sout(4) = sout(4) + cc*sx(1,0)*sy(0,1)*sz(0,0)
         tout(4) = tout(4) + cc*(tx(1,0)*sy(0,1)*sz(0,0) &
            + sx(1,0)*ty(0,1)*sz(0,0) &
            + sx(1,0)*sy(0,1)*tz(0,0))
         sout(5) = sout(5) + cc*sx(0,0)*sy(1,1)*sz(0,0)
         tout(5) = tout(5) + cc*(tx(0,0)*sy(1,1)*sz(0,0) &
            + sx(0,0)*ty(1,1)*sz(0,0) &
            + sx(0,0)*sy(1,1)*tz(0,0))
         sout(6) = sout(6) + cc*sx(0,0)*sy(0,1)*sz(1,0)
         tout(6) = tout(6) + cc*(tx(0,0)*sy(0,1)*sz(1,0) &
            + sx(0,0)*ty(0,1)*sz(1,0) &
            + sx(0,0)*sy(0,1)*tz(1,0))
         sout(7) = sout(7) + cc*sx(1,0)*sy(0,0)*sz(0,1)
         tout(7) = tout(7) + cc*(tx(1,0)*sy(0,0)*sz(0,1) &
            + sx(1,0)*ty(0,0)*sz(0,1) &
            + sx(1,0)*sy(0,0)*tz(0,1))
         sout(8) = sout(8) + cc*sx(0,0)*sy(1,0)*sz(0,1)
         tout(8) = tout(8) + cc*(tx(0,0)*sy(1,0)*sz(0,1) &
            + sx(0,0)*ty(1,0)*sz(0,1) &
            + sx(0,0)*sy(1,0)*tz(0,1))
         sout(9) = sout(9) + cc*sx(0,0)*sy(0,0)*sz(1,1)
         tout(9) = tout(9) + cc*(tx(0,0)*sy(0,0)*sz(1,1) &
            + sx(0,0)*ty(0,0)*sz(1,1) &
            + sx(0,0)*sy(0,0)*tz(1,1))

         ! --- nuclear attraction: one VRR per nucleus, accumulated ---
         vpref = 2.0_dp*PI/zeta*exp(-xi*rab2)
         do ic = 1, natm
            pcx = px - ratm(1, ic)
            pcy = py - ratm(2, ic)
            pcz = pz - ratm(3, ic)
            tval = zeta*(pcx*pcx + pcy*pcy + pcz*pcz)
            call boys_eval(2, tval, f)

            if (bet > al) then
            ! --- m = 2 ---
            vn(1,2) = vpref*f(2)
            ! --- m = 1 ---
            vn(1,1) = vpref*f(1)
            vn(2,1) = pbx*vn(1,1) - pcx*vn(1,2)
            vn(3,1) = pby*vn(1,1) - pcy*vn(1,2)
            vn(4,1) = pbz*vn(1,1) - pcz*vn(1,2)
            ! --- m = 0 ---
            vn(1,0) = vpref*f(0)
            vn(2,0) = pbx*vn(1,0) - pcx*vn(1,1)
            vn(3,0) = pby*vn(1,0) - pcy*vn(1,1)
            vn(4,0) = pbz*vn(1,0) - pcz*vn(1,1)
            vn(5,0) = pbx*vn(2,0) - pcx*vn(2,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(6,0) = pbx*vn(3,0) - pcx*vn(3,1)
            vn(7,0) = pbx*vn(4,0) - pcx*vn(4,1)
            vn(8,0) = pby*vn(3,0) - pcy*vn(3,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(9,0) = pby*vn(4,0) - pcy*vn(4,1)
            vn(10,0) = pbz*vn(4,0) - pcz*vn(4,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))

            do k = 1, 10
               vn0(k) = vn(k,0)
            end do

            vtmp(1) = bax*vn0(2) &
               + vn0(5)
            vtmp(2) = bay*vn0(2) &
               + vn0(6)
            vtmp(3) = baz*vn0(2) &
               + vn0(7)
            vtmp(4) = bax*vn0(3) &
               + vn0(6)
            vtmp(5) = bay*vn0(3) &
               + vn0(8)
            vtmp(6) = baz*vn0(3) &
               + vn0(9)
            vtmp(7) = bax*vn0(4) &
               + vn0(7)
            vtmp(8) = bay*vn0(4) &
               + vn0(9)
            vtmp(9) = baz*vn0(4) &
               + vn0(10)
            else
            ! --- m = 2 ---
            vn(1,2) = vpref*f(2)
            ! --- m = 1 ---
            vn(1,1) = vpref*f(1)
            vn(2,1) = pax*vn(1,1) - pcx*vn(1,2)
            vn(3,1) = pay*vn(1,1) - pcy*vn(1,2)
            vn(4,1) = paz*vn(1,1) - pcz*vn(1,2)
            ! --- m = 0 ---
            vn(1,0) = vpref*f(0)
            vn(2,0) = pax*vn(1,0) - pcx*vn(1,1)
            vn(3,0) = pay*vn(1,0) - pcy*vn(1,1)
            vn(4,0) = paz*vn(1,0) - pcz*vn(1,1)
            vn(5,0) = pax*vn(2,0) - pcx*vn(2,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(6,0) = pax*vn(3,0) - pcx*vn(3,1)
            vn(7,0) = pax*vn(4,0) - pcx*vn(4,1)
            vn(8,0) = pay*vn(3,0) - pcy*vn(3,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(9,0) = pay*vn(4,0) - pcy*vn(4,1)
            vn(10,0) = paz*vn(4,0) - pcz*vn(4,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))

            do k = 1, 10
               vn0(k) = vn(k,0)
            end do

            vtmp(1) = abx*vn0(2) &
               + vn0(5)
            vtmp(2) = abx*vn0(3) &
               + vn0(6)
            vtmp(3) = abx*vn0(4) &
               + vn0(7)
            vtmp(4) = aby*vn0(2) &
               + vn0(6)
            vtmp(5) = aby*vn0(3) &
               + vn0(8)
            vtmp(6) = aby*vn0(4) &
               + vn0(9)
            vtmp(7) = abz*vn0(2) &
               + vn0(7)
            vtmp(8) = abz*vn0(3) &
               + vn0(9)
            vtmp(9) = abz*vn0(4) &
               + vn0(10)
            end if

            do k = 1, 9
               vout(k) = vout(k) - cc*zatm(ic)*vtmp(k)
            end do
         end do
      end do
      end do
   end subroutine one_e_11

end module trc_1e_k11
